using J=boost::property_tree::ptree;
using V=Eigen::Vector3d;
namespace fs=std::filesystem;
namespace uw=underwater_wavemap_ros;
void require(bool ok,const std::string& why){if(!ok)throw std::runtime_error(why);}
std::vector<double> numbers(const J& j){std::vector<double> a;for(const auto& x:j)a.push_back(x.second.get_value<double>());return a;}
J vector(const V& v){J j;for(int i=0;i<3;++i){J x;x.put("",v[i]);j.push_back({"",x});}return j;}
struct Pose{V p;Eigen::Quaterniond q;};
Pose pose(const J& j){auto p=numbers(j.get_child("position")),q=numbers(j.get_child("quaternion_xyzw"));require(p.size()==3&&q.size()==4,"Invalid pose dimensions");Pose out{{p[0],p[1],p[2]},{q[3],q[0],q[1],q[2]}};require(out.p.allFinite()&&out.q.coeffs().allFinite()&&std::abs(out.q.squaredNorm()-1.)<1.e-3,"Invalid estimated camera pose");return out;}
struct Config{
 int width,height,stride,tree_height,threads;double fx,fy,cx,cy,fx_baseline,resolution,min_range,max_range,sigma,free_weight,occupied_weight,edge_abs,edge_rel,integration_rate;
 explicit Config(const J& m){const auto& p=m.get_child("mapper_parameters");width=m.get<int>("width");height=m.get<int>("height");fx=m.get<double>("fx");fy=m.get<double>("fy");cx=m.get<double>("cx");cy=m.get<double>("cy");fx_baseline=m.get<double>("fx_baseline_m_px");
  stride=p.get<int>("pixel_stride");tree_height=p.get<int>("tree_height");threads=p.get<int>("integration_threads");resolution=p.get<double>("min_cell_width_m");min_range=p.get<double>("min_range_m");max_range=p.get<double>("max_range_m");sigma=p.get<double>("range_sigma_m");free_weight=p.get<double>("scaling_free");occupied_weight=p.get<double>("scaling_occupied");edge_abs=p.get<double>("depth_edge_absolute_m");edge_rel=p.get<double>("depth_edge_relative");integration_rate=p.get<double>("integration_rate_hz");
  require(width>0&&height>0&&stride>0&&width%stride==0&&height%stride==0&&fx>0&&fy>0&&fx_baseline>0,"Invalid captured calibration");
  require(std::abs(resolution-.1)<1.e-6&&tree_height==6&&std::abs(min_range-.3)<1.e-6&&std::abs(max_range-8.)<1.e-6,"Replay requires the approved .1m/tree6/.3..8 configuration");
 }
};
std::vector<float> readFloats(const fs::path& path,size_t n){uint16_t endian=1;require(*reinterpret_cast<uint8_t*>(&endian)==1,"float32 LE reader needs little-endian host");require(fs::file_size(path)==n*sizeof(float),"Unexpected float32 image size: "+path.string());std::vector<float> a(n);std::ifstream in(path,std::ios::binary);in.read(reinterpret_cast<char*>(a.data()),n*sizeof(float));require(bool(in),"Image read failed");return a;}
fs::path relativeTo(const fs::path& manifest,const std::string& path){fs::path p(path);return p.is_absolute()?p:manifest.parent_path()/p;}
Eigen::MatrixXf decode(const std::vector<float>& raw,const Config& c,bool candidate){Eigen::MatrixXf d(c.height/c.stride,c.width/c.stride);for(int r=0;r<d.rows();++r)for(int col=0;col<d.cols();++col){const float z=raw[(r*c.stride)*c.width+col*c.stride];d(r,col)=candidate?uw::sanitizeDepthMeasurement(z,c.min_range):(!std::isfinite(z)||z<c.min_range||z>c.max_range?0.f:z);}uw::filterDepthEdges(&d,c.edge_abs,c.edge_rel);return d;}
class Fusion{
 public:
  wavemap::HashedChunkedWaveletOctree::Ptr map;
  wavemap::PinholeCameraProjector::Ptr projector;
  wavemap::PosedImage<>::Ptr image;
  std::shared_ptr<uw::ValidDepthContinuousRay> model;
  std::unique_ptr<wavemap::HashedChunkedWaveletIntegrator> integrator;
  explicit Fusion(const Config& c){wavemap::HashedChunkedWaveletOctreeConfig mc;mc.min_cell_width=c.resolution;mc.tree_height=c.tree_height;mc.min_log_odds=-2.f;mc.max_log_odds=4.f;map=std::make_shared<wavemap::HashedChunkedWaveletOctree>(mc);
   projector=std::make_shared<wavemap::PinholeCameraProjector>(wavemap::PinholeCameraProjectorConfig{float(c.fx/c.stride),float(c.fy/c.stride),float(c.cx/c.stride),float(c.cy/c.stride),c.height/c.stride,c.width/c.stride});
   // Production stores the transposed row-major depth image in Wavemap's image.
   image=std::make_shared<wavemap::PosedImage<>>(c.width/c.stride,c.height/c.stride);
   auto offsets=std::make_shared<wavemap::Image<wavemap::Vector2D>>(c.width/c.stride,c.height/c.stride);
   model=std::make_shared<uw::ValidDepthContinuousRay>(wavemap::ContinuousRayConfig{float(c.sigma),float(c.free_weight),float(c.occupied_weight)},projector,image);
   integrator=std::make_unique<wavemap::HashedChunkedWaveletIntegrator>(wavemap::ProjectiveIntegratorConfig{float(c.min_range),float(c.max_range)},projector,image,offsets,model,map,std::make_shared<wavemap::ThreadPool>(c.threads));
  }
  void integrate(const Eigen::MatrixXf& depth,const Pose& p){image->setPose(wavemap::Transformation3D(p.q.cast<float>(),p.p.cast<float>()));image->getData()=depth.transpose();integrator->integrate(*image);}
};
int state(const octomap::OcTree& tree,const V& p){auto* node=tree.search(p.x(),p.y(),p.z());return !node?2:tree.isNodeOccupied(node)?1:0;}
const char* stateName(int s){return s==0?"free":s==1?"occupied":"unknown";}
J counts(const std::array<size_t,3>& c){J j;j.put("free",c[0]);j.put("occupied",c[1]);j.put("unknown",c[2]);return j;}
std::vector<V> offsets(const V& box,double resolution){V step;for(int i=0;i<3;++i)step[i]=box[i]/std::ceil((box[i]+.001)/resolution);std::vector<V> out;for(double x=-box.x()/2.;x<=box.x()/2.;x+=step.x())for(double y=-box.y()/2.;y<=box.y()/2.;y+=step.y())for(double z=-box.z()/2.;z<=box.z()/2.;z+=step.z())out.emplace_back(x,y,z);return out;}
struct SelfMask{
 octomap::OcTreeKey low,high;
 SelfMask(const octomap::OcTree& tree,const V& body,const V& box){const V a=body-box/2.,b=body+box/2.;require(tree.coordToKeyChecked(a.x(),a.y(),a.z(),low)&&tree.coordToKeyChecked(b.x(),b.y(),b.z(),high),"Body outside OctoMap key range");}
 bool contains(const octomap::OcTreeKey& k)const{for(int i=0;i<3;++i)if(k[i]<low[i]||high[i]<k[i])return false;return true;}
};
int sourceLine(const octomap::OcTree& tree,const V& a,const V& b,const SelfMask& self,bool endpoint){octomap::KeyRay ray;require(tree.computeRayKeys({float(a.x()),float(a.y()),float(a.z())},{float(b.x()),float(b.y()),float(b.z())},ray),"Ray outside OctoMap");for(const auto& key:ray){auto* node=tree.search(key);if(!node){if(self.contains(key))continue;return 2;}if(tree.isNodeOccupied(node))return 1;}if(endpoint){const auto key=tree.coordToKey(float(b.x()),float(b.y()),float(b.z()));auto* node=tree.search(key);if(node&&tree.isNodeOccupied(node))return 1;if(!node&&!self.contains(key))return 2;}return 0;}
int bbox(const octomap::OcTree& tree,const V& body,const V& end,const V& box,bool endpoint){SelfMask self(tree,body,box);for(const auto& o:offsets(box,tree.getResolution())){const int s=sourceLine(tree,body+o,end+o,self,endpoint);if(s)return s;}return 0;}
J footprint(const octomap::OcTree& tree,const V& center,const V& box){std::array<size_t,3> c{};for(const auto& o:offsets(box,tree.getResolution()))++c[state(tree,center+o)];J j=counts(c);j.add_child("center",vector(center));return j;}
using Cell=std::array<int,3>;
using States=std::map<Cell,std::array<int,2>>;
void addStates(const octomap::OcTree& tree,int arm,States& out){const double res=tree.getResolution();for(auto it=tree.begin_leafs(),end=tree.end_leafs();it!=end;++it){const double size=it.getSize();const int width=std::llround(size/res);Cell low{int(std::llround((it.getX()-size/2.)/res)),int(std::llround((it.getY()-size/2.)/res)),int(std::llround((it.getZ()-size/2.)/res))};const int s=tree.isNodeOccupied(*it)?1:0;for(int x=0;x<width;++x)for(int y=0;y<width;++y)for(int z=0;z<width;++z){Cell cell{low[0]+x,low[1]+y,low[2]+z};auto added=out.emplace(cell,std::array<int,2>{2,2});added.first->second[arm]=s;}}}
J mapStats(const uw::Projection& p){J j;j.put("free_native_cells",p.stats.free_cells);j.put("occupied_native_cells",p.stats.occupied_cells);j.put("observed_wavemap_leaves",p.stats.observed_leaves);return j;}
J mapDelta(const octomap::OcTree& a,const octomap::OcTree& b,const Pose& camera,double max_range){States all;addStates(a,0,all);addStates(b,1,all);size_t transitions[3][3]{};std::array<size_t,2> beyond{},cap_occupied{};std::array<double,2> max_depth{-1.,-1.};const double res=a.getResolution();for(const auto& item:all){++transitions[item.second[0]][item.second[1]];const V world=(V(item.first[0],item.first[1],item.first[2])+V::Constant(.5))*res;const double z=(camera.q.conjugate()*(world-camera.p)).z();for(int arm=0;arm<2;++arm)if(item.second[arm]!=2){max_depth[arm]=std::max(max_depth[arm],z);if(z>max_range)++beyond[arm];if(std::abs(z-max_range)<=res&&item.second[arm]==1)++cap_occupied[arm];}}
 J j;for(int i=0;i<3;++i)for(int k=0;k<3;++k)j.put(std::string(stateName(i))+"_to_"+stateName(k),transitions[i][k]);j.put("union_observed_native_cells",all.size());for(int arm=0;arm<2;++arm){J x;x.put("observed_cell_centers_beyond_max_optical_depth_of_reference_camera",beyond[arm]);x.put("maximum_observed_cell_center_optical_depth_m",max_depth[arm]);x.put("occupied_centers_within_one_voxel_of_max_depth",cap_occupied[arm]);j.add_child(arm?"candidate_reference_camera_support":"baseline_reference_camera_support",x);}j.put("range_support_limit","Real maps combine multiple camera poses; beyond-range support relative to the last camera is descriptive, not evidence of that camera updating outside range. Synthetic identity-pose cases isolate native coarse-cell support.");return j;}
J contractChecks(const Config& c){J checks;bool passed=true;Pose identity{V::Zero(),Eigen::Quaterniond::Identity()};for(const auto& test:std::vector<std::pair<std::string,float>>{{"uniform_far_12m",12.f},{"uniform_just_over_max",float(c.max_range+1.e-4)},{"uniform_in_range_4m",4.f},{"all_invalid",0.f}}){Fusion f(c);std::vector<float> raw(size_t(c.width)*c.height,test.second);if(test.first=="all_invalid"){const float invalid[]={0.f,-1.f,std::numeric_limits<float>::quiet_NaN(),std::numeric_limits<float>::infinity(),float(c.min_range/2.)};for(size_t i=0;i<raw.size();++i)raw[i]=invalid[i%5];}f.integrate(decode(raw,c,true),identity);f.map->prune();auto p=uw::projectOctomap(*f.map,c.resolution);J j=mapStats(p);bool ok=test.first=="all_invalid"?(p.stats.free_cells==0&&p.stats.occupied_cells==0):test.first=="uniform_in_range_4m"?(p.stats.free_cells>0&&p.stats.occupied_cells>0):(p.stats.free_cells>0&&p.stats.occupied_cells==0);j.put("passed",ok);passed=passed&&ok;States cells;addStates(*p.tree,0,cells);size_t beyond=0;double maxz=-1.;for(const auto& cell:cells){const double z=(cell.first[2]+.5)*c.resolution;if(z>c.max_range)++beyond;maxz=std::max(maxz,z);}j.put("observed_centers_beyond_max_optical_depth",beyond);j.put("maximum_observed_center_optical_depth_m",maxz);j.put("strict_zero_beyond_max_is_asserted",false);checks.add_child(test.first,j);}checks.put("passed",passed);checks.put("range_semantics","Native camera max_range bounds optical Z. Coarse cells may straddle that boundary; all native support is reported without imposing a different integration algorithm.");return checks;}

int main(int argc,char** argv){try{
 require(argc==3||argc==4,"Usage: replay_far_rays MANIFEST.json RESULT.json [SAVE_MAP_PREFIX]");const fs::path manifest_path=argv[1];J manifest;boost::property_tree::read_json(manifest_path.string(),manifest);require(manifest.get<bool>("successful"),"Capture manifest is not successful");Config c(manifest);Fusion baseline(c),candidate(c);J result,frames;result.put("manifest",manifest_path.string());result.put("run",manifest.get<std::string>("run"));result.put("offline_map_only",true);result.put("ground_truth_used",false);result.put("initial_maps","Two empty HashedChunkedWaveletOctrees; this is a bounded captured-input A/B, not reconstruction of the complete live-run map.");result.add_child("mapper_parameters",manifest.get_child("mapper_parameters"));
 result.put("baseline_policy","Actual published .3..12m display depth, then original mapper finite/.3..8m validity and production edge filter/model.");result.put("candidate_policy","Raw acquisition-matched finite positive disparity -> float32 fx_baseline/disparity; production sanitizeDepthMeasurement has no upper measurement cutoff; same edge filter/model and native max optical depth8m.");
 uint64_t previous=0,last_integrated=0;size_t captured=0,fused=0,throttled=0;Pose final_camera{V::Zero(),Eigen::Quaterniond::Identity()};size_t derived_far=0,derived_beyond_display=0,total_baseline_retained=0,total_candidate_retained=0;const auto began=std::chrono::steady_clock::now();
 for(const auto& entry:manifest.get_child("frames")){const auto& f=entry.second;const uint64_t stamp=f.get<uint64_t>("stamp_ns");require(stamp>previous,"Capture order must have strictly increasing stamps");previous=stamp;require(f.get<uint64_t>("depth_stamp_ns")==stamp&&f.get<uint64_t>("disparity_stamp_ns")==stamp,"Depth/disparity acquisition mismatch");auto raw=readFloats(relativeTo(manifest_path,f.get<std::string>("depth_f32_le")),size_t(c.width)*c.height);auto disparity=readFloats(relativeTo(manifest_path,f.get<std::string>("disparity_f32_le")),raw.size());std::vector<float> far(raw.size(),0.f);size_t frame_far=0,frame_beyond_display=0,overlap=0;double max_depth_difference=0.;for(size_t i=0;i<far.size();++i){if(std::isfinite(disparity[i])&&disparity[i]>0.f)far[i]=float(c.fx_baseline)/disparity[i];if(std::isfinite(far[i])&&far[i]>c.max_range)++frame_far;if(std::isfinite(far[i])&&far[i]>12.)++frame_beyond_display;if(std::isfinite(raw[i])&&raw[i]>=.3&&raw[i]<=12.&&std::isfinite(far[i])){++overlap;max_depth_difference=std::max(max_depth_difference,std::abs(double(raw[i])-far[i]));}}
  auto a=decode(raw,c,false),b=decode(far,c,true);const size_t valid_a=(a.array()>0).count(),valid_b=(b.array()>0).count();total_baseline_retained+=valid_a;total_candidate_retained+=valid_b;derived_far+=frame_far;derived_beyond_display+=frame_beyond_display;final_camera=pose(f.get_child("camera_pose"));J row;row.put("stamp_ns",stamp);row.put("full_resolution_derived_depth_above_map_max",frame_far);row.put("full_resolution_derived_depth_above_display_max",frame_beyond_display);row.put("baseline_retained_downsampled_pixels",valid_a);row.put("candidate_retained_downsampled_pixels",valid_b);row.put("captured_display_vs_recomputed_overlap_pixels",overlap);row.put("captured_display_vs_recomputed_max_abs_difference_m",max_depth_difference);
  const bool integrate=!last_integrated||c.integration_rate<=0||(stamp-last_integrated)*1.e-9>=1./c.integration_rate;row.put("integrated_by_original_acquisition_stamp_throttle",integrate);if(integrate){baseline.integrate(a,final_camera);candidate.integrate(b,final_camera);last_integrated=stamp;++fused;}else ++throttled;frames.push_back({"",row});++captured;
 }
 require(captured>0,"No captured images");baseline.map->prune();candidate.map->prune();auto a=uw::projectOctomap(*baseline.map,c.resolution),b=uw::projectOctomap(*candidate.map,c.resolution);result.put("captured_frames",captured);result.put("fused_frames_per_arm",fused);result.put("frames_throttled_by_unchanged_rate",throttled);result.put("derived_pixels_above_map_max_all_captured",derived_far);result.put("derived_pixels_above_display_max_all_captured",derived_beyond_display);result.put("retained_pixels_all_captured_baseline",total_baseline_retained);result.put("retained_pixels_all_captured_candidate",total_candidate_retained);result.add_child("frames",frames);result.add_child("baseline_map",mapStats(a));result.add_child("candidate_map",mapStats(b));result.add_child("native_cell_delta",mapDelta(*a.tree,*b.tree,final_camera,c.max_range));
 const auto body_values=numbers(manifest.get_child("body_pose")),box_values=numbers(manifest.get_child("source_footprint"));require(body_values.size()==7&&box_values.size()==3,"Missing source body/footprint");V body(body_values[0],body_values[1],body_values[2]),box(box_values[0],box_values[1],box_values[2]);Eigen::Quaterniond body_q(body_values[6],body_values[3],body_values[4],body_values[5]);const auto rotation=body_q.toRotationMatrix();const double yaw=std::atan2(rotation(1,0),rotation(0,0));const V forward(std::cos(yaw),std::sin(yaw),0.);const double length=manifest.get<double>("extension_m")+manifest.get<double>("overshoot_m");J body_report;body_report.add_child("position",vector(body));body_report.add_child("horizontal_forward",vector(forward));body_report.add_child("source_footprint",vector(box));body_report.add_child("baseline",footprint(*a.tree,body,box));body_report.add_child("candidate",footprint(*b.tree,body,box));result.add_child("actual_body_footprint",body_report);
 J exits;size_t free_a=0,free_b=0,forward_free_a=0,forward_free_b=0;for(int x=-1;x<=1;++x)for(int y=-1;y<=1;++y)for(int z=-1;z<=1;++z){if(!x&&!y&&!z)continue;const V direction=V(x,y,z).normalized(),end=body+length*direction;const int sa=bbox(*a.tree,body,end,box,true),sb=bbox(*b.tree,body,end,box,true);const bool positive=direction.dot(forward)>0.;free_a+=sa==0;free_b+=sb==0;forward_free_a+=sa==0&&positive;forward_free_b+=sb==0&&positive;J row;row.add_child("direction",vector(direction));row.put("positive_current_body_heading_progress",positive);row.put("baseline_collision",stateName(sa));row.put("candidate_collision",stateName(sb));exits.push_back({"",row});}J exit_report;exit_report.put("length_with_source_overshoot_m",length);exit_report.put("baseline_free_exit_directions",free_a);exit_report.put("candidate_free_exit_directions",free_b);exit_report.put("baseline_forward_free_exit_directions",forward_free_a);exit_report.put("candidate_forward_free_exit_directions",forward_free_b);exit_report.add_child("directions",exits);exit_report.put("collision_semantics","Same source ray spacing/order, query-only current-body unknown exception, known occupied rejection, plus production native explicit endpoint samples. Forward hemisphere uses captured current body heading, not an invented task-start heading.");result.add_child("actual_body_exits",exit_report);
 J forward_samples;for(double distance:{.35,.5,1.,length}){J row;row.put("distance_m",distance);row.add_child("baseline_footprint",footprint(*a.tree,body+distance*forward,box));row.add_child("candidate_footprint",footprint(*b.tree,body+distance*forward,box));row.put("baseline_corridor",stateName(bbox(*a.tree,body,body+distance*forward,box,true)));row.put("candidate_corridor",stateName(bbox(*b.tree,body,body+distance*forward,box,true)));forward_samples.push_back({"",row});}result.add_child("actual_body_forward_samples",forward_samples);
 auto checks=contractChecks(c);const bool contract_passed=checks.get<bool>("passed");result.add_child("synthetic_native_contract_checks",checks);result.put("postprocessing","Same final production prune in both arms. Acquisition-stamp integration throttling is preserved; ROS reception/drop queues and intermediate publication scheduling are not replayed.");result.put("causal_limit","A/B isolates measurement retention on this bounded real captured batch. Improved map coverage does not establish the cause of every earlier unknown hole or guarantee a subsequent source-RRT branch or controller outcome.");result.put("elapsed_seconds",std::chrono::duration<double>(std::chrono::steady_clock::now()-began).count());
 if(argc==4){const std::string prefix=argv[3];require(wavemap::io::mapToFile(*baseline.map,prefix+"-baseline.wvmp")&&wavemap::io::mapToFile(*candidate.map,prefix+"-candidate.wvmp"),"Map save failed");require(a.tree->write(prefix+"-baseline.ot")&&b.tree->write(prefix+"-candidate.ot"),"OctoMap save failed");result.put("saved_map_prefix",prefix);}
 boost::property_tree::write_json(argv[2],result);std::cout<<"Captured "<<captured<<", fused "<<fused<<" per arm; free native cells "<<a.stats.free_cells<<" -> "<<b.stats.free_cells<<"; forward free exits "<<forward_free_a<<" -> "<<forward_free_b<<"; synthetic contract "<<(contract_passed?"PASS":"FAIL")<<'\n';return contract_passed?0:1;
 }catch(const std::exception& e){std::cerr<<"replay_far_rays: "<<e.what()<<'\n';return 2;}}
